  "name": "Payroll Reconciliation Tool",
  "description": "A professional tool to compare two payroll Excel files for discrepancies, featuring AI-powered change analysis."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface CellDiff {
  row: number;
  col: string; // Column letter (A, B, C...)
  valA: string | number | null;
  valB: string | number | null;
}

export interface SheetDiff {
  sheetName: string;
  hasDiff: boolean;
  status: 'identical' | 'modified' | 'missing_in_a' | 'missing_in_b';
  diffs: CellDiff[];
  rowCountA: number;
  rowCountB: number;
}

export interface ComparisonResult {
  isMatch: boolean;
  timestamp: number;
  sheets: SheetDiff[];
  summary: {
    totalSheets: number;
    matchingSheets: number;
    mismatchingSheets: number;
    totalDiffs: number;
  };
}

export interface FileData {
  name: string;
  size: number;
  content: ArrayBuffer;
}

import * as XLSX from 'xlsx';
import { ComparisonResult, SheetDiff, CellDiff } from '../types';

export const readExcelFile = async (file: File): Promise<ArrayBuffer> => {
  return await file.arrayBuffer();
};

const getColumnLetter = (colIndex: number): string => {
  let letter = '';
  while (colIndex >= 0) {
    letter = String.fromCharCode((colIndex % 26) + 65) + letter;
    colIndex = Math.floor(colIndex / 26) - 1;
  }
  return letter;
};

export const compareWorkbooks = (bufferA: ArrayBuffer, bufferB: ArrayBuffer): ComparisonResult => {
  const wbA = XLSX.read(bufferA, { type: 'array' });
  const wbB = XLSX.read(bufferB, { type: 'array' });

  const sheetsA = wbA.SheetNames;
  const sheetsB = wbB.SheetNames;

  const allSheets = Array.from(new Set([...sheetsA, ...sheetsB]));
  const sheetDiffs: SheetDiff[] = [];
  let totalDiffCount = 0;

  for (const sheetName of allSheets) {
    const sheetA = wbA.Sheets[sheetName];
    const sheetB = wbB.Sheets[sheetName];

    // Case 1: Missing in B
    if (sheetA && !sheetB) {
      sheetDiffs.push({
        sheetName,
        hasDiff: true,
        status: 'missing_in_b',
        diffs: [],
        rowCountA: 0,
        rowCountB: 0
      });
      continue;
    }

    // Case 2: Missing in A
    if (!sheetA && sheetB) {
      sheetDiffs.push({
        sheetName,
        hasDiff: true,
        status: 'missing_in_a',
        diffs: [],
        rowCountA: 0,
        rowCountB: 0
      });
      continue;
    }

    // Case 3: Present in both, compare content
    const jsonA: any[][] = XLSX.utils.sheet_to_json(sheetA, { header: 1, defval: null });
    const jsonB: any[][] = XLSX.utils.sheet_to_json(sheetB, { header: 1, defval: null });

    const diffs: CellDiff[] = [];
    const maxRows = Math.max(jsonA.length, jsonB.length);

    for (let r = 0; r < maxRows; r++) {
      const rowA = jsonA[r] || [];
      const rowB = jsonB[r] || [];
      const maxCols = Math.max(rowA.length, rowB.length);

      for (let c = 0; c < maxCols; c++) {
        const valA = rowA[c];
        const valB = rowB[c];

        // Loose equality check (eqeq) to handle string "100" vs number 100 often found in excel
        // But for strict payroll, we might want to be careful. Let's normalize nulls/undefineds.
        const cleanA = (valA === null || valA === undefined) ? '' : valA.toString().trim();
        const cleanB = (valB === null || valB === undefined) ? '' : valB.toString().trim();

        if (cleanA !== cleanB) {
          diffs.push({
            row: r + 1, // 1-based index for Excel users
            col: getColumnLetter(c),
            valA: valA,
            valB: valB
          });
        }
      }
    }

    totalDiffCount += diffs.length;
    sheetDiffs.push({
      sheetName,
      hasDiff: diffs.length > 0,
      status: diffs.length > 0 ? 'modified' : 'identical',
      diffs,
      rowCountA: jsonA.length,
      rowCountB: jsonB.length
    });
  }

  const mismatchingSheets = sheetDiffs.filter(s => s.status !== 'identical').length;

  return {
    isMatch: mismatchingSheets === 0,
    timestamp: Date.now(),
    sheets: sheetDiffs,
    summary: {
      totalSheets: allSheets.length,
      matchingSheets: allSheets.length - mismatchingSheets,
      mismatchingSheets,
      totalDiffs: totalDiffCount
    }
  };
};

import { GoogleGenAI } from "@google/genai";
import { ComparisonResult, SheetDiff } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }
  return new GoogleGenAI({ apiKey });
};

export const analyzeDifferences = async (comparison: ComparisonResult): Promise<string> => {
  const ai = getClient();

  // Filter for only relevant changes to send to LLM to avoid token limits
  const changesSummary = comparison.sheets
    .filter(s => s.status !== 'identical')
    .map(s => {
      if (s.status === 'missing_in_a') return `Sheet '${s.sheetName}' was added in the new file.`;
      if (s.status === 'missing_in_b') return `Sheet '${s.sheetName}' was removed in the new file.`;

      // Limit to first 20 diffs per sheet to save context, but give enough info
      const diffSamples = s.diffs.slice(0, 20).map(d => 
        `Row ${d.row}, Col ${d.col}: Old Value "${d.valA}" -> New Value "${d.valB}"`
      ).join('; ');

      const extraMsg = s.diffs.length > 20 ? `...and ${s.diffs.length - 20} more differences.` : '';

      return `Sheet '${s.sheetName}': ${s.diffs.length} discrepancies found. Samples: [${diffSamples} ${extraMsg}]`;
    })
    .join('\n\n');

  if (!changesSummary) {
    return "No differences found between the files.";
  }

  const prompt = `
    You are a payroll auditing assistant. I have compared two Excel payroll files and found the following discrepancies.
    Please provide a professional, concise summary of these changes. 
    Focus on patterns (e.g., "Salary updates in column E", "New employees added").
    Do not just list the changes again; interpret them.

    Here is the data:
    ${changesSummary}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: prompt,
    });
    return response.text || "Could not generate summary.";
  } catch (error) {
    console.error("Gemini Analysis Failed", error);
    return "Failed to generate AI analysis. Please ensure your API key is valid.";
  }
};

import React, { useRef, useState } from 'react';
import { Upload, FileSpreadsheet, CheckCircle, X } from 'lucide-react';

interface FileDropzoneProps {
  label: string;
  onFileSelect: (file: File) => void;
  selectedFileName?: string;
  onClear: () => void;
  colorClass?: string;
}

export const FileDropzone: React.FC<FileDropzoneProps> = ({ 
  label, 
  onFileSelect, 
  selectedFileName, 
  onClear,
  colorClass = "blue"
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      validateAndSetFile(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      validateAndSetFile(e.target.files[0]);
    }
  };

  const validateAndSetFile = (file: File) => {
    if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls') || file.name.endsWith('.csv')) {
      onFileSelect(file);
    } else {
      alert("Please upload a valid Excel file (.xlsx, .xls)");
    }
  };

  const borderColor = isDragging 
    ? `border-${colorClass}-500 bg-${colorClass}-50` 
    : `border-slate-300 hover:border-${colorClass}-400 hover:bg-slate-50`;

  return (
    <div className="w-full">
      <label className="block text-sm font-medium text-slate-700 mb-2">{label}</label>

      {!selectedFileName ? (
        <div
          onClick={() => inputRef.current?.click()}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          className={`relative border-2 border-dashed rounded-xl p-8 transition-all cursor-pointer flex flex-col items-center justify-center text-center h-48 ${borderColor}`}
        >
          <input 
            type="file" 
            ref={inputRef} 
            onChange={handleChange} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <div className={`p-3 rounded-full bg-${colorClass}-100 mb-3`}>
            <Upload className={`w-6 h-6 text-${colorClass}-600`} />
          </div>
          <p className="text-sm font-semibold text-slate-700">Click to upload or drag & drop</p>
          <p className="text-xs text-slate-500 mt-1">Excel files (.xlsx, .xls)</p>
        </div>
      ) : (
        <div className={`relative border border-${colorClass}-200 bg-${colorClass}-50 rounded-xl p-6 flex items-center justify-between h-48`}>
           <div className="flex items-center space-x-4">
              <div className={`p-3 rounded-full bg-white border border-${colorClass}-100 shadow-sm`}>
                <FileSpreadsheet className={`w-8 h-8 text-${colorClass}-600`} />
              </div>
              <div>
                <p className="text-sm font-semibold text-slate-800">{selectedFileName}</p>
                <p className="text-xs text-${colorClass}-600 flex items-center mt-1">
                  <CheckCircle className="w-3 h-3 mr-1" /> Ready for compare
                </p>
              </div>
           </div>
           <button 
             onClick={onClear}
             className="p-2 hover:bg-white rounded-full transition-colors text-slate-400 hover:text-red-500"
           >
             <X className="w-5 h-5" />
           </button>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { SheetDiff } from '../types';
import { ChevronDown, ChevronRight, AlertCircle, FilePlus, FileMinus } from 'lucide-react';

interface DetailedDiffProps {
  sheetDiff: SheetDiff;
}

export const DetailedDiff: React.FC<DetailedDiffProps> = ({ sheetDiff }) => {
  const [isOpen, setIsOpen] = useState(false);

  // Status Badge Logic
  let StatusIcon = AlertCircle;
  let statusColor = "text-yellow-600 bg-yellow-100 border-yellow-200";
  let statusText = "Modified";

  if (sheetDiff.status === 'identical') {
    statusColor = "text-green-600 bg-green-100 border-green-200";
    statusText = "Match";
  } else if (sheetDiff.status === 'missing_in_a') {
    StatusIcon = FilePlus;
    statusColor = "text-blue-600 bg-blue-100 border-blue-200";
    statusText = "New Sheet";
  } else if (sheetDiff.status === 'missing_in_b') {
    StatusIcon = FileMinus;
    statusColor = "text-red-600 bg-red-100 border-red-200";
    statusText = "Removed";
  }

  if (sheetDiff.status === 'identical') return null; // Don't show identical sheets in detail view

  return (
    <div className="border border-slate-200 rounded-lg overflow-hidden mb-3 shadow-sm bg-white">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-slate-100 transition-colors text-left"
      >
        <div className="flex items-center space-x-3">
          {isOpen ? <ChevronDown className="w-4 h-4 text-slate-500" /> : <ChevronRight className="w-4 h-4 text-slate-500" />}
          <span className="font-semibold text-slate-800">{sheetDiff.sheetName}</span>
          <span className={`text-xs px-2 py-0.5 rounded-full border flex items-center gap-1 ${statusColor}`}>
            <StatusIcon className="w-3 h-3" />
            {statusText}
          </span>
        </div>
        <span className="text-xs font-mono text-slate-500">
          {sheetDiff.diffs.length} difference(s)
        </span>
      </button>

      {isOpen && (
        <div className="p-0 overflow-x-auto">
          {sheetDiff.status === 'modified' ? (
            <table className="w-full text-sm text-left">
              <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                <tr>
                  <th className="px-6 py-3 w-24">Cell</th>
                  <th className="px-6 py-3 w-1/2">File A (Original)</th>
                  <th className="px-6 py-3 w-1/2">File B (New)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {sheetDiff.diffs.map((diff, idx) => (
                  <tr key={idx} className="hover:bg-yellow-50/50">
                    <td className="px-6 py-3 font-mono text-slate-500 bg-slate-50/50 font-semibold border-r border-slate-100">
                      {diff.col}{diff.row}
                    </td>
                    <td className="px-6 py-3 text-red-600 font-mono bg-red-50/30">
                      {diff.valA === null || diff.valA === '' ? <span className="text-slate-300 italic">(empty)</span> : diff.valA}
                    </td>
                    <td className="px-6 py-3 text-green-600 font-mono bg-green-50/30">
                      {diff.valB === null || diff.valB === '' ? <span className="text-slate-300 italic">(empty)</span> : diff.valB}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div className="p-6 text-slate-500 text-sm italic">
              {sheetDiff.status === 'missing_in_a' ? "This sheet exists only in the new file." : "This sheet exists only in the original file."}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { FileDropzone } from './components/FileDropzone';
import { DetailedDiff } from './components/DetailedDiff';
import { readExcelFile, compareWorkbooks } from './services/excelService';
import { analyzeDifferences } from './services/geminiService';
import { ComparisonResult } from './types';
import { 
  ArrowRightLeft, 
  CheckCircle2, 
  XCircle, 
  Sparkles, 
  Loader2,
  AlertTriangle,
  RefreshCw
} from 'lucide-react';

const App: React.FC = () => {
  const [fileA, setFileA] = useState<File | null>(null);
  const [fileB, setFileB] = useState<File | null>(null);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleCompare = async () => {
    if (!fileA || !fileB) return;
    setIsProcessing(true);
    setAiAnalysis(null);

    // Small delay to allow UI to update
    setTimeout(async () => {
      try {
        const bufferA = await readExcelFile(fileA);
        const bufferB = await readExcelFile(fileB);
        const result = compareWorkbooks(bufferA, bufferB);
        setComparisonResult(result);
      } catch (error) {
        console.error(error);
        alert("Error processing files. Please ensure they are valid Excel files.");
      } finally {
        setIsProcessing(false);
      }
    }, 100);
  };

  const handleAiAnalysis = async () => {
    if (!comparisonResult) return;
    setIsAnalyzing(true);
    try {
      const analysis = await analyzeDifferences(comparisonResult);
      setAiAnalysis(analysis);
    } catch (e) {
      setAiAnalysis("Failed to generate analysis.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleReset = () => {
    setFileA(null);
    setFileB(null);
    setComparisonResult(null);
    setAiAnalysis(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-blue-600 p-2 rounded-lg">
              <ArrowRightLeft className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-indigo-700">
              Payroll Reconciliation
            </h1>
          </div>
          <div className="flex items-center space-x-4">
             {comparisonResult && (
               <button 
                 onClick={handleReset}
                 className="text-sm font-medium text-slate-500 hover:text-slate-800 flex items-center"
               >
                 <RefreshCw className="w-4 h-4 mr-2" /> Start Over
               </button>
             )}
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Upload Section */}
        {!comparisonResult && (
          <div className="max-w-4xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-slate-800 mb-4">Compare Payroll Files</h2>
              <p className="text-slate-500 max-w-xl mx-auto">
                Upload your two Excel payroll files below. We'll verify they are identical or highlight the specific differences down to the cell level.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
              <FileDropzone 
                label="Original Payroll File (File A)" 
                onFileSelect={setFileA} 
                selectedFileName={fileA?.name} 
                onClear={() => setFileA(null)}
                colorClass="blue"
              />
              <FileDropzone 
                label="New Payroll File (File B)" 
                onFileSelect={setFileB} 
                selectedFileName={fileB?.name}
                onClear={() => setFileB(null)}
                colorClass="indigo"
              />
            </div>

            <div className="flex justify-center">
              <button
                disabled={!fileA || !fileB || isProcessing}
                onClick={handleCompare}
                className={`
                  flex items-center space-x-2 px-8 py-4 rounded-xl font-bold text-lg shadow-lg transition-all transform hover:-translate-y-1
                  ${(!fileA || !fileB) 
                    ? 'bg-slate-200 text-slate-400 cursor-not-allowed' 
                    : 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white hover:shadow-blue-200'}
                `}
              >
                {isProcessing ? (
                  <>
                    <Loader2 className="w-6 h-6 animate-spin" />
                    <span>Processing...</span>
                  </>
                ) : (
                  <>
                    <ArrowRightLeft className="w-6 h-6" />
                    <span>Compare Files</span>
                  </>
                )}
              </button>
            </div>
          </div>
        )}

        {/* Results Section */}
        {comparisonResult && (
          <div className="animate-in fade-in slide-in-from-bottom-8 duration-500">

            {/* Top Summary Card */}
            <div className={`
              rounded-2xl p-8 mb-8 flex flex-col md:flex-row items-center justify-between shadow-sm border
              ${comparisonResult.isMatch 
                ? 'bg-green-50 border-green-200' 
                : 'bg-white border-slate-200'}
            `}>
              <div className="flex items-center space-x-6 mb-4 md:mb-0">
                <div className={`
                  p-4 rounded-full 
                  ${comparisonResult.isMatch ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}
                `}>
                  {comparisonResult.isMatch ? <CheckCircle2 className="w-10 h-10" /> : <XCircle className="w-10 h-10" />}
                </div>
                <div>
                  <h2 className="text-2xl font-bold text-slate-800">
                    {comparisonResult.isMatch ? 'Files are Identical' : 'Discrepancies Found'}
                  </h2>
                  <p className="text-slate-500 mt-1">
                    Compared <span className="font-semibold text-slate-900">{comparisonResult.summary.totalSheets}</span> sheets. 
                    Found <span className="font-semibold text-slate-900">{comparisonResult.summary.totalDiffs}</span> individual cell differences.
                  </p>
                </div>
              </div>

              {!comparisonResult.isMatch && (
                 <button
                   onClick={handleAiAnalysis}
                   disabled={isAnalyzing || aiAnalysis !== null}
                   className="flex items-center space-x-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white px-6 py-3 rounded-lg font-semibold hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                   {isAnalyzing ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />}
                   <span>{aiAnalysis ? 'Analysis Complete' : 'Analyze with AI'}</span>
                 </button>
              )}
            </div>

            {/* AI Analysis Result */}
            {aiAnalysis && (
              <div className="bg-gradient-to-br from-purple-50 to-pink-50 border border-purple-100 rounded-xl p-6 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                   <Sparkles className="w-24 h-24 text-purple-600" />
                </div>
                <h3 className="text-lg font-bold text-purple-900 flex items-center mb-3">
                  <Sparkles className="w-5 h-5 mr-2 text-purple-600" /> AI Insight
                </h3>
                <div className="prose prose-purple max-w-none text-slate-700 leading-relaxed whitespace-pre-wrap">
                  {aiAnalysis}
                </div>
              </div>
            )}

            {/* Detailed Diffs */}
            <div className="space-y-6">
              <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                <AlertTriangle className="w-5 h-5 mr-2 text-slate-400" />
                Detailed Report
              </h3>

              {comparisonResult.sheets.filter(s => s.status !== 'identical').length === 0 ? (
                <div className="text-center p-12 bg-white rounded-xl border border-dashed border-slate-300">
                  <p className="text-slate-500">All sheets match perfectly. No details to show.</p>
                </div>
              ) : (
                <div className="space-y-2">
                  {comparisonResult.sheets.map((sheet) => (
                    <DetailedDiff key={sheet.sheetName} sheetDiff={sheet} />
                  ))}
                </div>
              )}
            </div>

          </div>
        )}
      </main>
    </div>
  );
};

export default App;

