    Do not just list the changes again; interpret them.

    Here is the data:
    ${changesSummary}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Could not generate summary.";
  } catch (error) {
    console.error("Gemini Analysis Failed", error);
    return "Failed to generate AI analysis. Please ensure your API key is valid.";
  }
};

export interface CellDiff {
  row: number; // Row number in the new file (or original if missing)
  col: string; // Column letter
  columnHeader?: string; // e.g., "Basic Salary"
  recordId?: string; // e.g., "SG02235 - Aburime, Peter"
  valA: string | number | null;
  valB: string | number | null;
}

export interface SheetDiff {
  sheetName: string;
  hasDiff: boolean;
  status: 'identical' | 'modified' | 'missing_in_a' | 'missing_in_b';
  diffs: CellDiff[];
  totalsMatch?: boolean; // True if a "Total" row was found and matched perfectly
  totalsDiffs?: CellDiff[]; // Specific differences in the totals row
  rowCountA: number;
  rowCountB: number;
  reordered?: boolean; // Flag to indicate if data matched but was reordered
}

export interface ComparisonResult {
  isMatch: boolean;
  timestamp: number;
  sheets: SheetDiff[];
  summary: {
    totalSheets: number;
    matchingSheets: number;
    mismatchingSheets: number;
