import * as XLSX from 'xlsx';
import { ComparisonResult, SheetDiff, CellDiff } from '../types';

export const readExcelFile = async (file: File): Promise<ArrayBuffer> => {
  return await file.arrayBuffer();
};

const getColumnLetter = (colIndex: number): string => {
  let letter = '';
  while (colIndex >= 0) {
    letter = String.fromCharCode((colIndex % 26) + 65) + letter;
    colIndex = Math.floor(colIndex / 26) - 1;
  }
  return letter;
};

// Helper to clean values for comparison (handles "100" vs 100, null vs undefined)
const normalizeVal = (val: any): string => {
  if (val === null || val === undefined) return '';
  // Round numbers to 2 decimals to avoid float precision issues (0.01999999 vs 0.02)
  if (typeof val === 'number') {
    return Math.round(val * 100).toString(); 
  }
  return val.toString().trim();
};

const formatVal = (val: any): string => {
   if (val === null || val === undefined) return '';
   return val.toString();
}

interface RowData {
  rowNum: number;
  data: any[];
  id: string; // The unique key for this row
}

export const compareWorkbooks = (bufferA: ArrayBuffer, bufferB: ArrayBuffer): ComparisonResult => {
  const wbA = XLSX.read(bufferA, { type: 'array' });
  const wbB = XLSX.read(bufferB, { type: 'array' });

  const sheetsA = wbA.SheetNames;
  const sheetsB = wbB.SheetNames;

  const allSheets = Array.from(new Set([...sheetsA, ...sheetsB]));
  const sheetDiffs: SheetDiff[] = [];
  let totalDiffCount = 0;

  for (const sheetName of allSheets) {
    const sheetA = wbA.Sheets[sheetName];
    const sheetB = wbB.Sheets[sheetName];

    // Case 1 & 2: Missing Sheets
    if ((sheetA && !sheetB) || (!sheetA && sheetB)) {
      sheetDiffs.push({
        sheetName,
        hasDiff: true,
        status: !sheetB ? 'missing_in_b' : 'missing_in_a',
        diffs: [],
        rowCountA: sheetA ? XLSX.utils.sheet_to_json(sheetA).length : 0,
        rowCountB: sheetB ? XLSX.utils.sheet_to_json(sheetB).length : 0
      });
      continue;
    }

    // Convert to JSON (array of arrays)
    const rawA: any[][] = XLSX.utils.sheet_to_json(sheetA, { header: 1, defval: null, blankrows: false });
    const rawB: any[][] = XLSX.utils.sheet_to_json(sheetB, { header: 1, defval: null, blankrows: false });

    // --- SMART ANALYSIS START ---

    // 1. Find Header Row (heuristic: row with most strings)
    const findHeaderRow = (rows: any[][]) => {
      let bestRow = 0;
      let maxStrings = 0;
      // Search first 20 rows
      for (let i = 0; i < Math.min(rows.length, 20); i++) {
        const strCount = rows[i].filter(c => typeof c === 'string' && c.length > 1).length;
        if (strCount > maxStrings) {
          maxStrings = strCount;
          bestRow = i;
        }
      }
      return bestRow;
    };

    const headerRowIndexA = findHeaderRow(rawA);
    const headers = rawA[headerRowIndexA] || [];

    // 2. Identify Key Column (ID, Staff No, or Name)
    let keyColIndex = -1;
    const keyKeywords = ['staff id', 'employee id', 'id', 'staff no', 'employee no', 'reference', 'code'];

    // First pass: explicit IDs
    for (let i = 0; i < headers.length; i++) {
      const h = String(headers[i]).toLowerCase();
      if (keyKeywords.some(k => h.includes(k))) {
        keyColIndex = i;
        break;
      }
    }
    // Second pass: Name
    if (keyColIndex === -1) {
      for (let i = 0; i < headers.length; i++) {
        const h = String(headers[i]).toLowerCase();
        if (h.includes('name') || h.includes('employee')) {
          keyColIndex = i;
          break;
        }
      }
    }

    // 3. Find Total Row (usually at bottom, starts with "Total")
    const findTotalRow = (rows: any[][]) => {
      // Look from bottom up
      for (let i = rows.length - 1; i >= 0; i--) {
        const row = rows[i];
        if (!row) continue;
        // Check first 5 columns for "Total"
        for (let c = 0; c < Math.min(row.length, 5); c++) {
           if (row[c] && String(row[c]).toLowerCase().includes('total')) {
             return { index: i, row: row };
           }
        }
      }
      return null;
    };

    const totalRowA = findTotalRow(rawA);
    const totalRowB = findTotalRow(rawB);

    // 4. Extract Data Rows (excluding header and total)
    // We map ID -> Row Data
    const mapRows = (rows: any[][], headerIdx: number, keyIdx: number, totalIdx: number | undefined) => {
      const map = new Map<string, RowData>();
      const duplicates = new Set<string>();

      rows.forEach((row, rIdx) => {
        if (rIdx <= headerIdx) return; // Skip header and above
        if (totalIdx !== undefined && rIdx === totalIdx) return; // Skip total row
        if (!row || row.length === 0) return; // Skip empty

        // Generate Key
        let key = '';
        if (keyIdx !== -1 && row[keyIdx]) {
          key = String(row[keyIdx]).trim();
        } else {
          // Fallback if no key column found or value missing: use entire row string
          // This reverts to essentially row-by-row but allows reordering if exact duplicate exists
          key = `ROW_CONTENT_${row.join('|')}`;
        }

        if (map.has(key)) {
          duplicates.add(key); // Track duplicates just in case
          // Append row number to key to make unique if duplicated ID found (rare in payroll but possible)
          key = `${key}_DUP_${rIdx}`; 
        }

        map.set(key, { rowNum: rIdx + 1, data: row, id: key });
      });
      return map;
    };

    const mapA = mapRows(rawA, headerRowIndexA, keyColIndex, totalRowA?.index);
    const mapB = mapRows(rawB, findHeaderRow(rawB), keyColIndex, totalRowB?.index);

    // 5. Compare Data
    const sheetDiffsList: CellDiff[] = [];

    // Check for records in A (Original) against B
    for (const [key, rowObjA] of mapA.entries()) {
      const rowObjB = mapB.get(key);

      if (!rowObjB) {
        // Missing in B
        sheetDiffsList.push({
          row: rowObjA.rowNum,
          col: keyColIndex !== -1 ? getColumnLetter(keyColIndex) : '?',
          columnHeader: 'Entire Row',
          recordId: key,
          valA: 'Present',
          valB: 'Missing in New File'
        });
      } else {
        // Exists in both, compare columns
        const rowA = rowObjA.data;
        const rowB = rowObjB.data;
        const maxCols = Math.max(rowA.length, rowB.length);

        for (let c = 0; c < maxCols; c++) {
           // Skip Key column if it's the ID itself, unless we want to verify it exactly matches (it does by definition of map get)

           const valA = rowA[c];
           const valB = rowB[c];

           if (normalizeVal(valA) !== normalizeVal(valB)) {
             sheetDiffsList.push({
               row: rowObjB.rowNum, // Report row in New File
               col: getColumnLetter(c),
               columnHeader: headers[c] ? String(headers[c]) : undefined,
               recordId: key,
               valA: formatVal(valA),
               valB: formatVal(valB)
             });
           }
        }

        // Remove from mapB so we know what's left
        mapB.delete(key);
      }
    }

    // Check for leftover records in B (New records)
    for (const [key, rowObjB] of mapB.entries()) {
      sheetDiffsList.push({
        row: rowObjB.rowNum,
        col: keyColIndex !== -1 ? getColumnLetter(keyColIndex) : '?',
        columnHeader: 'Entire Row',
        recordId: key,
        valA: 'Missing in Original',
        valB: 'New Record'
      });
    }

    // 6. Compare Totals
    let totalsMatch = undefined;
    const totalsDiffs: CellDiff[] = [];

    if (totalRowA && totalRowB) {
      totalsMatch = true;
      const tA = totalRowA.row;
      const tB = totalRowB.row;
      const maxTC = Math.max(tA.length, tB.length);

      for (let c = 0; c < maxTC; c++) {
        // Skip label columns (e.g. the cell saying "Total:")
        if (String(tA[c]).toLowerCase().includes('total')) continue;

        if (normalizeVal(tA[c]) !== normalizeVal(tB[c])) {
          totalsMatch = false;
          totalsDiffs.push({
            row: totalRowB.index + 1,
            col: getColumnLetter(c),
            columnHeader: headers[c] ? String(headers[c]) : undefined,
            recordId: 'TOTALS',
            valA: formatVal(tA[c]),
            valB: formatVal(tB[c])
          });
        }
      }
    } else if (totalRowA || totalRowB) {
      // One has total, one doesn't
      totalsMatch = false;
      totalsDiffs.push({
        row: totalRowB ? totalRowB.index + 1 : 0,
        col: '-',
        columnHeader: 'Structure',
        recordId: 'TOTALS',
        valA: totalRowA ? 'Total Row Present' : 'Total Row Missing',
        valB: totalRowB ? 'Total Row Present' : 'Total Row Missing',
      });
    }

    totalDiffCount += sheetDiffsList.length + totalsDiffs.length;

    // Determine status
    let status: SheetDiff['status'] = 'identical';
    if (sheetDiffsList.length > 0 || (totalsMatch === false)) {
      status = 'modified';
    }

    // Check if reordered (Identical content but different row numbers implies reorder, 
    // but our map logic abstracts row numbers. If we have 0 diffs but maps were built, it's a match.)
    // We implicitly support reordering by using the Map. 

    sheetDiffs.push({
      sheetName,
      hasDiff: status !== 'identical',
      status,
      diffs: sheetDiffsList,
      totalsMatch,
      totalsDiffs,
      rowCountA: rawA.length,
      rowCountB: rawB.length
    });
  }

  const mismatchingSheets = sheetDiffs.filter(s => s.status !== 'identical').length;

  return {
    isMatch: mismatchingSheets === 0,
    timestamp: Date.now(),
    sheets: sheetDiffs,
    summary: {
      totalSheets: allSheets.length,
      matchingSheets: allSheets.length - mismatchingSheets,
      mismatchingSheets,
      totalDiffs: totalDiffCount
    }
  };
};

