import { GoogleGenAI } from "@google/genai";
import { ComparisonResult, SheetDiff } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }
  return new GoogleGenAI({ apiKey });
};

export const analyzeDifferences = async (comparison: ComparisonResult): Promise<string> => {
  const ai = getClient();

  // Filter for only relevant changes to send to LLM to avoid token limits
  const changesSummary = comparison.sheets
    .filter(s => s.status !== 'identical' || (s.totalsMatch === false))
    .map(s => {
      let parts = [];
      if (s.status === 'missing_in_a') return `Sheet '${s.sheetName}' was added.`;
      if (s.status === 'missing_in_b') return `Sheet '${s.sheetName}' was removed.`;

      if (s.totalsMatch === false) {
         parts.push(`CRITICAL: Totals row does NOT match.`);
      }

      if (s.diffs.length > 0) {
        // Limit to first 15 diffs per sheet
        const diffSamples = s.diffs.slice(0, 15).map(d => 
          `ID: ${d.recordId} | Field: ${d.columnHeader || d.col} | Old: "${d.valA}" -> New: "${d.valB}"`
        ).join('\n');

        const extraMsg = s.diffs.length > 15 ? `...and ${s.diffs.length - 15} more differences.` : '';
        parts.push(`Record discrepancies:\n${diffSamples}\n${extraMsg}`);
      } else {
        parts.push("Records match (rows may be reordered).");
      }

      return `Sheet '${s.sheetName}':\n${parts.join('\n')}`;
    })
    .join('\n\n---\n\n');

  if (!changesSummary) {
    return "The files appear to be identical in content. Rows may have been reordered, but all employee records and totals match.";
  }

  const prompt = `
    You are a payroll auditing expert. I have compared two Excel payroll files using an intelligent matching algorithm that ignores row order (identifying employees by ID/Name) and verifies footer totals.

    Here are the discrepancies found:
    ${changesSummary}

    Please provide a professional executive summary.
    1. First, state clearly if the TOTALS match or mismatch. This is the most important check.
    2. Then, summarize the record-level changes. Identify patterns (e.g. "Employee X, Y, Z received a housing allowance increase").
    3. Ignore simple row reordering unless data actually changed.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Could not generate summary.";
  } catch (error) {
    console.error("Gemini Analysis Failed", error);
    return "Failed to generate AI analysis. Please ensure your API key is valid.";
  }
};

