};

// Robust normalization for currency and numbers
const normalizeVal = (val: any): string => {
  if (val === null || val === undefined) return '';

  let str = String(val);

  // 1. Handle "1,234.56" vs 1234.56 (remove commas)
  // Only remove commas if it looks like a number
  if (/^[\d,.-]+$/.test(str)) {
    str = str.replace(/,/g, '');
  }

  // 2. Parse Float
  const num = parseFloat(str);

  // 3. Round if number
  if (!isNaN(num) && isFinite(num)) {
    // Round to 2 decimals to handle floating point math
    return Math.round(num * 100).toString(); 
  }

  return str.trim();
};

const formatVal = (val: any): string => {
   if (val === null || val === undefined) return '';
   return val.toString();
}

interface RowData {
