    const sheetB = wbB.Sheets[sheetName];

    // Case 1 & 2: Missing Sheets
    if ((sheetA && !sheetB) || (!sheetA && sheetB)) {
      sheetDiffs.push({
        sheetName,
        hasDiff: true,
        status: !sheetB ? 'missing_in_b' : 'missing_in_a',
        diffs: [],
        rowCountA: sheetA ? XLSX.utils.sheet_to_json(sheetA).length : 0,
        rowCountB: sheetB ? XLSX.utils.sheet_to_json(sheetB).length : 0
      });
      continue;
    }

    // Convert to JSON
    const rawA: any[][] = XLSX.utils.sheet_to_json(sheetA, { header: 1, defval: null, blankrows: false });
    const rawB: any[][] = XLSX.utils.sheet_to_json(sheetB, { header: 1, defval: null, blankrows: false });

    // --- SMART ANALYSIS START ---

    // 1. Find Header Row
    const findHeaderRow = (rows: any[][]) => {
      let bestRow = 0;
      let maxStrings = 0;
      for (let i = 0; i < Math.min(rows.length, 25); i++) {
        if (!rows[i]) continue;
        const strCount = rows[i].filter(c => typeof c === 'string' && c.length > 1).length;
        if (strCount > maxStrings) {
          maxStrings = strCount;
          bestRow = i;
        }
      }
      return bestRow;
    };

    const headerRowIndexA = findHeaderRow(rawA);
    const headers = rawA[headerRowIndexA] || [];

    // 2. Identify Key Column
    let keyColIndex = -1;
    const keyKeywords = ['staff id', 'employee id', 'id', 'staff no', 'employee no', 'reference', 'code'];
    for (let i = 0; i < headers.length; i++) {
      const h = String(headers[i]).toLowerCase();
      if (keyKeywords.some(k => h.includes(k))) {
        keyColIndex = i;
        break;
      }
    }
    if (keyColIndex === -1) {
      for (let i = 0; i < headers.length; i++) {
        const h = String(headers[i]).toLowerCase();
        if (h.includes('name') || h.includes('employee')) {
          keyColIndex = i;
          break;
        }
      }
    }

    // 3. Find Total Row - AGGRESSIVE SEARCH
    const findTotalRow = (rows: any[][]) => {
      // Look from bottom up, up to 50 rows
      const searchLimit = Math.max(0, rows.length - 50);
      for (let i = rows.length - 1; i >= searchLimit; i--) {
        const row = rows[i];
        if (!row) continue;

        // Convert whole row to string to fuzzy match "Total" if it's not in the first few columns
        const rowStr = row.join(' ').toLowerCase();
        if (rowStr.includes('total') || rowStr.includes('sum')) {
           return { index: i, row: row };
        }
      }
      return null;
    };

    const totalRowA = findTotalRow(rawA);
    const totalRowB = findTotalRow(rawB);

    // 4. Map Rows Logic (Same as before)
    const mapRows = (rows: any[][], headerIdx: number, keyIdx: number, totalIdx: number | undefined) => {
      const map = new Map<string, RowData>();
      rows.forEach((row, rIdx) => {
        if (rIdx <= headerIdx) return;
        if (totalIdx !== undefined && rIdx === totalIdx) return;
        if (!row || row.length === 0) return;

        let key = '';
        if (keyIdx !== -1 && row[keyIdx]) {
          key = String(row[keyIdx]).trim();
        } else {
          key = `ROW_CONTENT_${row.join('|')}`;
        }

        // Handle explicit duplicates by appending index if needed, 
        // but for payroll we assume IDs are unique usually.
        if (map.has(key)) {
           key = `${key}_DUP_${rIdx}`;
        }

        map.set(key, { rowNum: rIdx + 1, data: row, id: key });
      });
      return map;
    };

    const mapA = mapRows(rawA, headerRowIndexA, keyColIndex, totalRowA?.index);
    const mapB = mapRows(rawB, findHeaderRow(rawB), keyColIndex, totalRowB?.index);

    // 5. Compare Data Rows
    const sheetDiffsList: CellDiff[] = [];

    for (const [key, rowObjA] of mapA.entries()) {
      const rowObjB = mapB.get(key);

      if (!rowObjB) {
        sheetDiffsList.push({
          row: rowObjA.rowNum,
          col: keyColIndex !== -1 ? getColumnLetter(keyColIndex) : '?',
          columnHeader: 'Entire Row',
          recordId: key,
          valA: 'Present',
          valB: 'Missing in New File'
        });
      } else {
        const rowA = rowObjA.data;
        const rowB = rowObjB.data;
        const maxCols = Math.max(rowA.length, rowB.length);

        for (let c = 0; c < maxCols; c++) {
           const valA = rowA[c];
           const valB = rowB[c];

           if (normalizeVal(valA) !== normalizeVal(valB)) {
             sheetDiffsList.push({
               row: rowObjB.rowNum,
               col: getColumnLetter(c),
               columnHeader: headers[c] ? String(headers[c]) : undefined,
               recordId: key,
               valA: formatVal(valA),
               valB: formatVal(valB)
             });
           }
        }
        mapB.delete(key);
      }
    }

    for (const [key, rowObjB] of mapB.entries()) {
      sheetDiffsList.push({
        row: rowObjB.rowNum,
        col: keyColIndex !== -1 ? getColumnLetter(keyColIndex) : '?',
        columnHeader: 'Entire Row',
        recordId: key,
        valA: 'Missing in Original',
        valB: 'New Record'
      });
    }

    // 6. Compare Totals
    let totalsMatch = undefined;
    const totalsDiffs: CellDiff[] = [];

    if (totalRowA && totalRowB) {
      sheetsWithTotalsCount++;
      totalsMatch = true;
      const tA = totalRowA.row;
      const tB = totalRowB.row;
      const maxTC = Math.max(tA.length, tB.length);

      for (let c = 0; c < maxTC; c++) {
        // Skip label columns by checking if it's text 'Total'
        const valAStr = String(tA[c]).toLowerCase();
        if (valAStr.includes('total') || valAStr.includes('sum')) continue;

        // Skip empty cells in total row
        if (!tA[c] && !tB[c]) continue;

        if (normalizeVal(tA[c]) !== normalizeVal(tB[c])) {
          totalsMatch = false;
          anyTotalsMismatch = true;
          totalsDiffs.push({
            row: totalRowB.index + 1,
            col: getColumnLetter(c),
            columnHeader: headers[c] ? String(headers[c]) : undefined,
            recordId: 'TOTALS',
            valA: formatVal(tA[c]),
            valB: formatVal(tB[c])
          });
        }
      }
    } else if (totalRowA || totalRowB) {
      // Only one has total row
      totalsMatch = false;
      anyTotalsMismatch = true;
      totalsDiffs.push({
        row: totalRowB ? totalRowB.index + 1 : 0,
        col: '-',
        columnHeader: 'Structure',
        recordId: 'TOTALS',
        valA: totalRowA ? 'Total Row Present' : 'Missing',
        valB: totalRowB ? 'Total Row Present' : 'Missing',
      });
    }

    totalDiffCount += sheetDiffsList.length + totalsDiffs.length;

    let status: SheetDiff['status'] = 'identical';
    if (sheetDiffsList.length > 0 || (totalsMatch === false)) {
      status = 'modified';
    }

    sheetDiffs.push({
      sheetName,
      hasDiff: status !== 'identical',
      status,
      diffs: sheetDiffsList,
      totalsMatch,
      totalsDiffs,
      rowCountA: rawA.length,
      rowCountB: rawB.length
    });
  }

  const mismatchingSheets = sheetDiffs.filter(s => s.status !== 'identical').length;

  // Determine Global Reconciliation Status
  let reconciliationStatus: ReconciliationStatus = 'success';
  if (anyTotalsMismatch) {
    reconciliationStatus = 'failure';
  } else if (mismatchingSheets > 0) {
    // If totals match (or no totals found) but rows have diffs -> Warning
    reconciliationStatus = 'warning';
  }

  return {
    isMatch: mismatchingSheets === 0,
    reconciliationStatus,
    timestamp: Date.now(),
    sheets: sheetDiffs,
    summary: {
      totalSheets: allSheets.length,
      matchingSheets: allSheets.length - mismatchingSheets,
      mismatchingSheets,
      totalDiffs: totalDiffCount,
      sheetsWithTotals: sheetsWithTotalsCount
    }
  };
};

import React, { useState } from 'react';
import { SheetDiff } from '../types';
import { ChevronDown, ChevronRight, AlertCircle, FilePlus, FileMinus, Calculator, Check, X, ShieldCheck, AlertTriangle } from 'lucide-react';

interface DetailedDiffProps {
  sheetDiff: SheetDiff;
}

export const DetailedDiff: React.FC<DetailedDiffProps> = ({ sheetDiff }) => {
  const [isOpen, setIsOpen] = useState(false);

  // Status Badge Logic
  let StatusIcon = AlertCircle;
  let statusColor = "text-yellow-600 bg-yellow-100 border-yellow-200";
  let cardBorder = "border-yellow-200";
  let statusText = "Differences Found";

  // Logic: 
  // 1. Totals Match = GREEN (Success)
  // 2. Totals Mismatch = RED (Failure)
  // 3. No Totals + Diffs = YELLOW (Warning)

  if (sheetDiff.totalsMatch === true) {
    if (sheetDiff.diffs.length > 0) {
       // Totals match, but rows have noise
       statusColor = "text-green-700 bg-green-100 border-green-200";
       cardBorder = "border-green-200";
       statusText = "Totals Match (with Row Warnings)";
       StatusIcon = ShieldCheck;
    } else {
       // Perfect Match
       statusColor = "text-green-700 bg-green-100 border-green-200";
       cardBorder = "border-green-200";
       statusText = "Reconciled";
       StatusIcon = Check;
    }
  } else if (sheetDiff.totalsMatch === false) {
    statusColor = "text-red-700 bg-red-100 border-red-200";
    cardBorder = "border-red-200";
    statusText = "Totals Mismatch";
    StatusIcon = X;
  } else if (sheetDiff.status === 'identical') {
    statusColor = "text-green-700 bg-green-100 border-green-200";
    cardBorder = "border-green-200";
    statusText = "Match";
    StatusIcon = Check;
  } else if (sheetDiff.status === 'missing_in_a') {
    StatusIcon = FilePlus;
    statusColor = "text-blue-700 bg-blue-100 border-blue-200";
    cardBorder = "border-blue-200";
    statusText = "New Sheet";
  } else if (sheetDiff.status === 'missing_in_b') {
    StatusIcon = FileMinus;
    statusColor = "text-red-700 bg-red-100 border-red-200";
    cardBorder = "border-red-200";
    statusText = "Removed";
  }

  return (
    <div className={`border rounded-lg overflow-hidden mb-3 shadow-sm bg-white ${cardBorder}`}>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-slate-100 transition-colors text-left"
      >
        <div className="flex items-center space-x-3">
          {isOpen ? <ChevronDown className="w-4 h-4 text-slate-500" /> : <ChevronRight className="w-4 h-4 text-slate-500" />}
          <span className="font-bold text-slate-800 text-lg">{sheetDiff.sheetName}</span>

          <span className={`text-xs px-3 py-1 rounded-full border flex items-center gap-1 font-medium ${statusColor}`}>
            <StatusIcon className="w-3.5 h-3.5" />
            {statusText}
          </span>
        </div>
        <div className="flex items-center gap-4 text-xs font-mono text-slate-500">
           <span>{sheetDiff.rowCountA} rows (Old)</span>
           <span>→</span>
           <span>{sheetDiff.rowCountB} rows (New)</span>
        </div>
      </button>

      {isOpen && (
        <div className="p-0 overflow-x-auto">

          {/* 1. TOTALS SECTION (Priority) */}
          {sheetDiff.totalsMatch === false && sheetDiff.totalsDiffs && (
             <div className="bg-red-50 p-6 border-b border-red-100">
                <h4 className="text-red-800 font-bold flex items-center mb-4 text-lg">
                   <X className="w-5 h-5 mr-2" />
                   Totals Verification Failed
                </h4>
                <div className="overflow-x-auto bg-white rounded-lg border border-red-200 shadow-sm">
                  <table className="w-full text-sm text-left">
                     <thead className="bg-red-50">
                        <tr className="text-red-700 border-b border-red-200">
                           <th className="px-4 py-2">Column</th>
                           <th className="px-4 py-2">Original Total</th>
                           <th className="px-4 py-2">New Total</th>
                        </tr>
                     </thead>
                     <tbody>
                        {sheetDiff.totalsDiffs.map((d, i) => (
                           <tr key={i} className="font-mono text-red-900 border-b last:border-0 border-red-50">
                              <td className="px-4 py-3 font-semibold">{d.columnHeader || d.col}</td>
                              <td className="px-4 py-3">{d.valA}</td>
                              <td className="px-4 py-3 bg-red-100/50">{d.valB}</td>
                           </tr>
                        ))}
                     </tbody>
                  </table>
                </div>
             </div>
          )}

          {sheetDiff.totalsMatch === true && (
             <div className="bg-green-50 p-4 border-b border-green-100 flex items-center text-green-800 font-medium">
                <Check className="w-5 h-5 mr-2" />
                Totals Verified & Matched Successfully.
             </div>
          )}

          {/* 2. RECORDS SECTION */}
          {sheetDiff.status === 'modified' && sheetDiff.diffs.length > 0 ? (
            <div className="p-0">
               {sheetDiff.totalsMatch === true && (
                  <div className="bg-yellow-50 px-6 py-3 border-b border-yellow-100 text-yellow-800 text-sm flex items-center">
                     <AlertTriangle className="w-4 h-4 mr-2" />
                     However, {sheetDiff.diffs.length} row discrepancies were found. Check if these are expected.
                  </div>
               )}

              <table className="w-full text-sm text-left">
                <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                  <tr>
                    <th className="px-6 py-3 w-1/3">Record / Identifier</th>
                    <th className="px-6 py-3 w-48">Column</th>
                    <th className="px-6 py-3 w-1/4">File A (Original)</th>
                    <th className="px-6 py-3 w-1/4">File B (New)</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {sheetDiff.diffs.map((diff, idx) => (
                    <tr key={idx} className="hover:bg-yellow-50/50">
                      <td className="px-6 py-3 text-slate-700 font-medium border-r border-slate-100">
                         <div className="flex flex-col">
                            <span className="font-mono text-blue-600">{diff.recordId}</span>
                            <span className="text-xs text-slate-400">Row {diff.row} in new file</span>
                         </div>
                      </td>
                      <td className="px-6 py-3 text-slate-600">
                         <span className="font-semibold">{diff.columnHeader || `Col ${diff.col}`}</span>
                      </td>
                      <td className="px-6 py-3 text-red-600 font-mono bg-red-50/30">
                        {diff.valA === null || diff.valA === '' ? <span className="text-slate-300 italic">(empty)</span> : diff.valA}
                      </td>
                      <td className="px-6 py-3 text-green-600 font-mono bg-green-50/30">
                        {diff.valB === null || diff.valB === '' ? <span className="text-slate-300 italic">(empty)</span> : diff.valB}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}

          {sheetDiff.status === 'identical' && (
             <div className="p-6 text-slate-400 italic text-center">No differences found in this sheet.</div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { FileDropzone } from './components/FileDropzone';
import { DetailedDiff } from './components/DetailedDiff';
import { readExcelFile, compareWorkbooks } from './services/excelService';
import { analyzeDifferences } from './services/geminiService';
import { ComparisonResult } from './types';
import { 
  ArrowRightLeft, 
  CheckCircle2, 
  XCircle, 
  Sparkles, 
  Loader2,
  AlertTriangle,
  RefreshCw,
  ShieldCheck,
  ShieldAlert
} from 'lucide-react';

const App: React.FC = () => {
  const [fileA, setFileA] = useState<File | null>(null);
  const [fileB, setFileB] = useState<File | null>(null);
  const [comparisonResult, setComparisonResult] = useState<ComparisonResult | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleCompare = async () => {
    if (!fileA || !fileB) return;
    setIsProcessing(true);
    setAiAnalysis(null);

    setTimeout(async () => {
      try {
        const bufferA = await readExcelFile(fileA);
        const bufferB = await readExcelFile(fileB);
        const result = compareWorkbooks(bufferA, bufferB);
        setComparisonResult(result);
      } catch (error) {
        console.error(error);
        alert("Error processing files. Please ensure they are valid Excel files.");
      } finally {
        setIsProcessing(false);
      }
    }, 100);
  };

  const handleAiAnalysis = async () => {
    if (!comparisonResult) return;
    setIsAnalyzing(true);
    try {
      const analysis = await analyzeDifferences(comparisonResult);
      setAiAnalysis(analysis);
    } catch (e) {
      setAiAnalysis("Failed to generate analysis.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleReset = () => {
    setFileA(null);
    setFileB(null);
    setComparisonResult(null);
    setAiAnalysis(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-blue-600 p-2 rounded-lg">
              <ArrowRightLeft className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-indigo-700">
              Payroll Reconciliation
            </h1>
          </div>
          <div className="flex items-center space-x-4">
             {comparisonResult && (
               <button 
                 onClick={handleReset}
                 className="text-sm font-medium text-slate-500 hover:text-slate-800 flex items-center"
               >
                 <RefreshCw className="w-4 h-4 mr-2" /> Start Over
               </button>
             )}
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {!comparisonResult && (
          <div className="max-w-4xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-slate-800 mb-4">Compare Payroll Files</h2>
              <p className="text-slate-500 max-w-xl mx-auto">
                Upload your two Excel payroll files below. We'll verify they are identical or highlight the specific differences down to the cell level.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
              <FileDropzone 
                label="Original Payroll File (File A)" 
                onFileSelect={setFileA} 
                selectedFileName={fileA?.name} 
                onClear={() => setFileA(null)}
                colorClass="blue"
              />
              <FileDropzone 
                label="New Payroll File (File B)" 
                onFileSelect={setFileB} 
                selectedFileName={fileB?.name}
                onClear={() => setFileB(null)}
                colorClass="indigo"
              />
            </div>

            <div className="flex justify-center">
              <button
                disabled={!fileA || !fileB || isProcessing}
                onClick={handleCompare}
                className={`
                  flex items-center space-x-2 px-8 py-4 rounded-xl font-bold text-lg shadow-lg transition-all transform hover:-translate-y-1
                  ${(!fileA || !fileB) 
                    ? 'bg-slate-200 text-slate-400 cursor-not-allowed' 
                    : 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white hover:shadow-blue-200'}
                `}
              >
                {isProcessing ? (
                  <>
                    <Loader2 className="w-6 h-6 animate-spin" />
                    <span>Processing...</span>
                  </>
                ) : (
                  <>
                    <ArrowRightLeft className="w-6 h-6" />
                    <span>Compare Files</span>
                  </>
                )}
              </button>
            </div>
          </div>
        )}

        {comparisonResult && (
          <div className="animate-in fade-in slide-in-from-bottom-8 duration-500">

            {/* Top Summary Card */}
            <div className={`
              rounded-2xl p-8 mb-8 flex flex-col md:flex-row items-center justify-between shadow-sm border
              ${comparisonResult.reconciliationStatus === 'success' 
                ? 'bg-green-50 border-green-200' 
                : comparisonResult.reconciliationStatus === 'warning'
                  ? 'bg-yellow-50 border-yellow-200'
                  : 'bg-red-50 border-red-200'}
            `}>
              <div className="flex items-center space-x-6 mb-4 md:mb-0">
                <div className={`
                  p-4 rounded-full 
                  ${comparisonResult.reconciliationStatus === 'success' 
                    ? 'bg-green-100 text-green-600' 
                    : comparisonResult.reconciliationStatus === 'warning'
                      ? 'bg-yellow-100 text-yellow-600'
                      : 'bg-red-100 text-red-600'}
                `}>
                  {comparisonResult.reconciliationStatus === 'success' && <CheckCircle2 className="w-10 h-10" />}
                  {comparisonResult.reconciliationStatus === 'warning' && <ShieldAlert className="w-10 h-10" />}
                  {comparisonResult.reconciliationStatus === 'failure' && <XCircle className="w-10 h-10" />}
                </div>
                <div>
                  <h2 className="text-2xl font-bold text-slate-800">
                    {comparisonResult.reconciliationStatus === 'success' && 'Reconciliation Successful'}
                    {comparisonResult.reconciliationStatus === 'warning' && 'Totals Match (With Warnings)'}
                    {comparisonResult.reconciliationStatus === 'failure' && 'Reconciliation Failed'}
                  </h2>
                  <p className="text-slate-600 mt-2 text-sm leading-relaxed">
                    {comparisonResult.reconciliationStatus === 'success' && 
                       "All totals match perfectly across all sheets. No major discrepancies found."}
                    {comparisonResult.reconciliationStatus === 'warning' && 
                       "Financial totals match perfectly, but some individual rows have discrepancies."}
                    {comparisonResult.reconciliationStatus === 'failure' && 
                       "Critical financial discrepancies found. Totals do not match."}
                  </p>
                </div>
              </div>

              <button
                   onClick={handleAiAnalysis}
                   disabled={isAnalyzing || aiAnalysis !== null}
                   className="flex items-center space-x-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white px-6 py-3 rounded-lg font-semibold hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                   {isAnalyzing ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />}
                   <span>{aiAnalysis ? 'Analysis Complete' : 'Analyze with AI'}</span>
              </button>
            </div>

            {/* AI Analysis Result */}
            {aiAnalysis && (
              <div className="bg-gradient-to-br from-purple-50 to-pink-50 border border-purple-100 rounded-xl p-6 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10">
                   <Sparkles className="w-24 h-24 text-purple-600" />
                </div>
                <h3 className="text-lg font-bold text-purple-900 flex items-center mb-3">
                  <Sparkles className="w-5 h-5 mr-2 text-purple-600" /> AI Insight
                </h3>
                <div className="prose prose-purple max-w-none text-slate-700 leading-relaxed whitespace-pre-wrap">
                  {aiAnalysis}
                </div>
              </div>
            )}

            {/* Detailed Diffs */}
            <div className="space-y-6">
              <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                <ShieldCheck className="w-5 h-5 mr-2 text-slate-400" />
                Sheet Breakdown
              </h3>

              <div className="space-y-2">
                {comparisonResult.sheets.map((sheet) => (
                  <DetailedDiff key={sheet.sheetName} sheetDiff={sheet} />
                ))}
              </div>
            </div>

          </div>
        )}
      </main>
    </div>
  );
};

