            ];

            const wsDetail = XLSX.utils.aoa_to_sheet(detailAOA);
            wsDetail['!cols'] = [{ wch: 50 }, { wch: 20 }, { wch: 20 }, { wch: 20 }, { wch: 20 }, { wch: 40 }];

            const detailDataStartRow = 3;
