                                </table>
                            </div>
                        </div>
                    )}
                </div>
            </main>

            <footer className="fixed bottom-4 right-4 text-xs text-slate-500 font-medium opacity-80 z-50">
                &copy; IBRAHIM O.
            </footer>
        </div>
    );
};

